<?php namespace App\Http\Controllers; use App\Models\{Cart,CartItem,Offer,Order,OrderItem}; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB;
class CartController extends Controller { private function cart(){return Cart::firstOrCreate(['user_id'=>auth()->id()]);} public function show(){return view('orders.cart',['cart'=>$this->cart()->load('items.offer.medicine','items.offer.organization')]);} public function add(Offer $offer,Request $r){abort_unless($offer->is_active,404);$d=$r->validate(['quantity'=>'nullable|integer|min:1|max:999']);$item=CartItem::firstOrNew(['cart_id'=>$this->cart()->id,'offer_id'=>$offer->id]);$item->quantity=($item->exists?$item->quantity:0)+($d['quantity']??1);$item->unit_price=$offer->price;$item->snapshot=['medicine'=>$offer->medicine->name,'supplier'=>$offer->organization->name,'price'=>$offer->price];$item->save();return back()->with('success','Товар добавлен в корзину.');} public function update(CartItem $item,Request $r){abort_unless($item->cart->user_id===auth()->id(),403);$item->update($r->validate(['quantity'=>'required|integer|min:1|max:999']));return back();} public function checkout(){ $cart=$this->cart()->load('items.offer'); abort_if($cart->items->isEmpty(),422); DB::transaction(function()use($cart){$checkout=DB::table('checkouts')->insertGetId(['buyer_organization_id'=>auth()->user()->organization_id,'user_id'=>auth()->id(),'created_at'=>now(),'updated_at'=>now()]); foreach($cart->items->groupBy(fn($i)=>$i->offer->organization_id) as $supplier=>$items){$total=$items->sum(fn($i)=>$i->quantity*$i->unit_price);$order=Order::create(['checkout_id'=>$checkout,'buyer_organization_id'=>auth()->user()->organization_id,'supplier_organization_id'=>$supplier,'total'=>$total]);foreach($items as $i) OrderItem::create(['order_id'=>$order->id,'offer_id'=>$i->offer_id,'medicine_id'=>$i->offer->medicine_id,'quantity'=>$i->quantity,'unit_price'=>$i->unit_price,'snapshot'=>$i->snapshot]);} $cart->items()->delete();});return redirect()->route('orders.index')->with('success','Заказы переданы поставщикам.');} }
